(function($) {

    var pet_row_count = parseInt( $('.cp-edit-account-pet-row').length );

    /*
     * Remove pet row
     */
    $('.cp-edit-account-pet-rows').on('click', '.cp-edit-account-pet-row-remove', function() {
        if( $('.cp-edit-account-pet-row').length > 1) {
            // Remove the row
            $(this).parents('.cp-edit-account-pet-row').first().remove();
        } else {
            // Clear the row's contents
            $(this).parents('.cp-edit-account-pet-row').find(':input').not(':checkbox, :submit').val('');
        }

    });

    /*
     * Add new pet row
     */
    $('.cp-edit-account-pet-row-add').on('click', function() {

        pet_row_count++;

        var row = $('.cp-edit-account-pet-row').first().clone().wrap('<p/>').parent().html();

        if(row) {
            row = row.replace(/pet-row_[0-9+]/igm, 'pet-row_' + pet_row_count);
            row = row.replace(/pet_information_name_[0-9+]/igm, 'pet_information_name_' + pet_row_count);
            row = row.replace(/pet_information_age_[0-9+]/igm, 'pet_information_age_' + pet_row_count);
            row = row.replace(/pet_information_date_[0-9+]/igm, 'pet_information_date_' + pet_row_count);
            row = row.replace(/pet-row-remove_[0-9+]/igm, 'pet-row-remove_' + pet_row_count);
            row = row.replace(/pet_information\[[0-9+]\]/igm, 'pet_information[' + pet_row_count + ']');
            row = row.replace(/value=".*"/igm, 'value=""');

            $('.cp-edit-account-pet-rows').append(row);

            $("input.hasDatepicker").removeClass("hasDatepicker");
            $("input.datepicker").datepicker("destroy");
            $('input.datepicker').datepicker({
                dateFormat: 'mm/dd/yy',
                changeYear: true,
                yearRange: "-25:+0"
            }).focus(function () {
                $(".ui-datepicker-year").show();
            });
        }

    });

    $('input.datepicker').datepicker({
        dateFormat: 'mm/dd/yy',
        changeYear: true,
        yearRange: "-25:+0"
    }).focus(function () {
        $(".ui-datepicker-year").show();
    });

    $('input.datepicker-mm-dd').datepicker({
        dateFormat: 'mm/dd',
        changeYear: false
    }).focus(function () {
        $(".ui-datepicker-year").hide();
    });

})(jQuery);